/* What each part of each figure in figures.js means: FIG_NOTES[key] = { nodes: { id: { d, links } },
   edges: { "a>b": { d } }, walk: [ids in the order to explain them] }. Read by figures/viewer.js. */
window.FIG_NOTES = Object.assign(window.FIG_NOTES || {}, {
  "arc": {"nodes": {"words": {"d": "Week 1 of the systems track: building the vocabulary for everything that follows — throughput, latency, queues, backpressure — the words used to describe how a system behaves under load.", "links": [{"label": "Session: throughput, latency, queues, backpressure", "url": "index.html#/s/1/1"}]}, "partitioning": {"d": "Week 2 of the systems track: how work and data get split across more than one machine, and what that split costs.", "links": [{"label": "Session: how work splits", "url": "index.html#/s/2/1"}]}, "storage": {"d": "Week 3 of the systems track: where a hundred million things actually live — the storage engines and indexes underneath everything drawn so far.", "links": [{"label": "Session: where a hundred million things live", "url": "index.html#/s/3/1"}]}, "failure": {"d": "Week 4 of the systems track: what breaks, and how, once a system is running at a hundred million things.", "links": [{"label": "Session: things break at a hundred million", "url": "index.html#/s/4/1"}]}, "caching": {"d": "Week 5 of the systems track: caching, and putting the whole systems track together into one coherent picture."}, "logs": {"d": "Week 1 of the mathematics track: functions, exponentials and logarithms — the algebraic vocabulary the rest of the track is built from.", "links": [{"label": "Session: functions, exponentials, logarithms", "url": "index.html#/s/1/2"}]}, "derivatives": {"d": "Week 2 of the mathematics track: derivatives, done properly rather than as a memorized rule.", "links": [{"label": "Session: derivatives, properly", "url": "index.html#/s/2/2"}]}, "vectors": {"d": "Week 3 of the mathematics track: vectors and matrices, the language linear algebra and later gradients are expressed in.", "links": [{"label": "Session: vectors and matrices", "url": "index.html#/s/3/2"}]}, "gradients": {"d": "Week 4 of the mathematics track: gradients and descent — how a model's parameters move toward lower loss.", "links": [{"label": "Session: gradients and descent", "url": "index.html#/s/4/2"}]}, "probability": {"d": "Week 5 of the mathematics track: probability, the last topic before the milestone-1 gate."}, "the-gate": {"d": "The checkpoint at the end of milestone 1: proof that both tracks are ready before moving on to milestone 2, which is TrenTorch and DSA."}}, "edges": {"words>partitioning": {"d": "Vocabulary such as throughput and queue depth is used immediately once the topic turns to splitting work across machines."}, "logs>derivatives": {"d": "Logarithms and exponentials are the building blocks derivatives are then applied to."}, "partitioning>storage": {"d": "Splitting work assumes there is state to split; week 3 asks where that state actually lives."}, "derivatives>vectors": {"d": "Single-variable derivatives generalize to gradients over vectors, the next topic."}, "storage>failure": {"d": "Once data has a home, week 4 asks what happens when the machines holding it fail."}, "vectors>gradients": {"d": "Vector and matrix operations are the language gradients are expressed in."}, "failure>caching": {"d": "Handling failure well is a precondition for caching safely — a cache that does not know a backend failed serves stale data with full confidence."}, "gradients>probability": {"d": "Gradient descent's stochasticity is the bridge into thinking about probability directly."}, "caching>the-gate": {"d": "The systems track's last topic feeds into the milestone checkpoint."}, "probability>the-gate": {"d": "The mathematics track's last topic feeds into the same checkpoint — both tracks are required to pass it."}}, "walk": ["words", "words>partitioning", "partitioning", "partitioning>storage", "storage", "storage>failure", "failure", "failure>caching", "caching", "logs", "logs>derivatives", "derivatives", "derivatives>vectors", "vectors", "vectors>gradients", "gradients", "gradients>probability", "probability", "caching>the-gate", "probability>the-gate", "the-gate"]},
  "attention": {"nodes": {"q": {"d": "The query vector: what the current token is looking for.\n\nIt is compared against every key in the sequence via a dot product to decide how much attention to pay to each other position.", "links": [{"label": "Session: embeddings and attention, at mechanism level", "url": "index.html#/s/4/3"}]}, "k": {"d": "The key vector: what each position offers to be matched against.\n\nA large dot product between a query and a key means that position is relevant to what the query is looking for.", "links": [{"label": "TrenTorch module source: attention", "url": "https://github.com/TrenTorch/TrenTorch/tree/main/data/src/12_attention"}]}, "v": {"d": "The value vector: what actually gets carried forward once attention decides how much to weight this position.\n\nQuery and key only decide the weights; V is the content mixed together according to those weights to form the output."}, "qk": {"d": "The raw attention score, Q · K, a dot product summed over the dₖ dimensions of the vectors.\n\nBecause it sums dₖ independent terms, its variance grows in proportion to dₖ — the fact the whole scaling trick is built on.", "links": [{"label": "AI Engineering from Scratch: self-attention from scratch", "url": "https://github.com/rohitg00/ai-engineering-from-scratch/tree/main/phases/07-transformers-deep-dive/02-self-attention-from-scratch"}]}, "scale": {"d": "The score after dividing by √dₖ.\n\nDividing by the standard deviation, not the variance, brings the scaled score back to roughly unit variance regardless of how large dₖ is — with dₖ = 64, that means dividing by 8.", "links": [{"label": "System design guide: context budget under attention cost", "url": "SYSTEM%20DESIGN.html#/patterns/llm-cost/context-budget"}]}, "softmax": {"d": "The normalised attention weights: one non-negative number per position, summing to 1.\n\nFed unscaled scores (std ≈ 8 here), softmax saturates — one weight near 1 and the rest near 0 — and its gradient collapses to almost nothing at that point."}, "output": {"d": "The attention output: the value vectors combined, weighted by the softmax distribution.\n\nThis is the actual payload attention produces for the next layer — softmax alone only produces weights, it is V that is being weighted."}, "unscaled-softmax": {"d": "The softmax output when scores are not divided by √dₖ, sketched as one bar per position.\n\nOne bar dominates almost completely; the model can no longer get a useful gradient out of this position because the weight is already saturated near 1 or 0."}, "scaled-softmax": {"d": "The softmax output after scores are divided by √dₖ.\n\nWeight is spread across several positions instead of collapsing onto one, which keeps the gradient informative during training."}}, "edges": {"q>qk": {"d": "Q is dotted against every key to produce a raw score per position."}, "k>qk": {"d": "K is the other side of the same dot product."}, "qk>scale": {"d": "The raw score is divided by √dₖ to control its variance."}, "scale>softmax": {"d": "The scaled scores are normalised into a probability distribution over positions."}, "softmax>output": {"d": "The softmax weights are used to combine values into the output."}, "v>output": {"d": "V is the content being weighted; softmax only supplies the weights, this edge supplies what gets weighted."}}, "walk": ["q", "k", "q>qk", "k>qk", "qk", "qk>scale", "scale", "scale>softmax", "softmax", "v", "v>output", "softmax>output", "output", "unscaled-softmax", "scaled-softmax"]},
  "bayes": {"nodes": {"people": {"d": "The population being tested: 100,000 people, most of whom are healthy.\n\nEverything downstream depends on how this population splits between ill and healthy — the base rate the whole example turns on.", "links": [{"label": "Session: probability", "url": "index.html#/s/5/2"}]}, "ill": {"d": "The 100 people out of 100,000 who actually have the condition, a base rate of 0.1%.\n\nA test with 99% sensitivity catches 99 of them; the other 1 is a false negative."}, "healthy": {"d": "The 99,900 people who do not have the condition.\n\nThis pool is 999 times larger than the ill pool, so even a small false-positive rate applied to it produces a large absolute number of wrong positives.", "links": [{"label": "Wikipedia: base rate fallacy", "url": "https://en.wikipedia.org/wiki/Base_rate_fallacy"}]}, "pos-from-ill": {"d": "The 99 true positives: ill people the test correctly flags, at 99% sensitivity.\n\nThis is the number most people picture when they hear \"99% accurate test\" — and it is the smaller of the two positive groups by a wide margin.", "links": [{"label": "AI Engineering from Scratch: Bayes theorem", "url": "https://github.com/rohitg00/ai-engineering-from-scratch/tree/main/phases/01-math-foundations/07-bayes-theorem"}]}, "pos-from-healthy": {"d": "The 4,995 false positives: healthy people the test incorrectly flags, at a 5% false-positive rate applied to a pool of 99,900.\n\n99,900 x 0.05 = 4,995 — nearly fifty times more false positives than true positives, purely because the healthy pool is so much larger."}}, "edges": {"people>ill": {"d": "100,000 x 0.001 = 100 people actually have the condition."}, "people>healthy": {"d": "100,000 x 0.999 = 99,900 people do not."}, "ill>pos-from-ill": {"d": "99% sensitivity: 100 x 0.99 = 99 ill people test positive."}, "healthy>pos-from-healthy": {"d": "5% false-positive rate: 99,900 x 0.05 = 4,995 healthy people test positive anyway."}}, "walk": ["people", "people>ill", "ill", "ill>pos-from-ill", "pos-from-ill", "people>healthy", "healthy", "healthy>pos-from-healthy", "pos-from-healthy"]},
  "benchLoop": {"nodes": {"production": {"d": "Real conversations between users and the agent, with every tool call and its result recorded. The bench only ever starts from something that actually happened, never from an imagined test case.\n\nAt alfred_ this is 5,000-plus active users' email and calendar sessions, kept in your own tables in Supabase Postgres."}, "scanner": {"d": "A daily job that runs cheap, deterministic checks over the day's conversations and flags anything that looks like one of twelve failure types: the agent claims an action no tool performed, the user repeats themselves, a tool errors and the agent carries on.\n\nDeterministic signals are fast and free but over-fire, which is why a judge sits after them.", "links": [{"label": "Technique: shadow mode and online signals", "url": "SYSTEM%20DESIGN.html#/patterns/grounding/shadow-online"}]}, "llm-judge": {"d": "An LLM that reads each flag with its context (the user turn, the agent turn, the tool traces and two turns either side) and decides whether it is a genuine bug. Its rubric was built from about a week of flags labelled by hand.\n\nIt agrees with a human on roughly three in four, and is reconciled weekly against fresh labels, because what counts as correct changes as features change.", "links": [{"label": "Eugene Yan: evaluating LLM evaluators", "url": "https://eugeneyan.com/writing/llm-evaluators/"}]}, "fix-then-promote": {"d": "A genuine bug is fixed by hand, then promoted into the bench. A reconciler decides whether to add a new case, update an existing one, or merge the failure into a case that already covers it, so the bench does not fill with near-duplicates."}, "bench": {"d": "The regression suite: a little over a hundred cases, each a real failure with its own snapshot of the user's world. About ten percent are flaky and run three times, reporting a pass rate.", "links": [{"label": "Technique: eval suites as release gates", "url": "SYSTEM%20DESIGN.html#/patterns/grounding/eval-gate"}]}, "replay": {"d": "The real agent runs each case from the CLI with a harness flag. Tool code runs for real; only the call to Gmail, the calendar or an MCP server is routed to the case's SQLite snapshot, which answers in the provider's shape. Writes land in the snapshot, so a task created at turn two is visible at turn three.", "links": [{"label": "Technique: environment snapshots", "url": "SYSTEM%20DESIGN.html#/patterns/agent-durability/env-snapshots"}]}, "score": {"d": "Deterministic assertions against the snapshot (the right tools, the right records, every event in the window present), then an LLM judge for what cannot be enumerated, such as a summary's quality. The headline number is tool calls per completed task: 2.5 falling to 2.2 means the same outcome, found faster."}, "sign-off": {"d": "What the bench is for: comparing the old and new agent on the same cases before shipping. It signed off the rewrite of multi-turn orchestration, pointing at exactly which cases got better, which got worse, and why."}}, "edges": {"production>scanner": {"d": "Runs daily over the previous day's conversations."}, "scanner>llm-judge": {"d": "Each flag travels with its evidence: the turns, the tool traces and the agent's reasoning."}, "llm-judge>fix-then-promote": {"d": "Only flags the judge calls genuine move on; roughly three in four."}, "fix-then-promote>bench": {"d": "Added, updated or merged, never duplicated."}, "bench>replay": {"d": "The full bench nightly, about half an hour; a change to one tool runs only the fifteen to thirty cases whose snapshots touch it."}, "replay>score": {"d": "Every run is scored the same way, so versions are comparable."}, "score>sign-off": {"d": "A release decision backed by named cases, not opinions."}}, "walk": ["production", "production>scanner", "scanner", "llm-judge", "fix-then-promote", "bench", "replay", "score", "sign-off"]},
  "biasVarianceKnobs": {"nodes": {"train-curve": {"d": "Training error as model complexity increases, left panel.\n\nIt falls smoothly and keeps falling: a model with enough capacity can memorise the training set outright, so a low training error alone is never proof that the model has learned anything general."}, "val-curve": {"d": "Validation error as model complexity increases, left panel.\n\nIt falls alongside the training error at first, reaches a minimum, then rises again as the model starts fitting noise specific to the training set rather than the underlying pattern. Where it turns upward is the over-fitting boundary."}, "naive-fit": {"d": "A model chosen by pushing complexity up until training error looks best, ignoring that the validation curve has already turned.\n\nIts validation error is worse than a properly regularised model at lower complexity, even though its training error is the lowest on the chart."}, "regularized-fit": {"d": "The point regularisation pulls an over-fit model back to: enough complexity to fit the pattern, not enough to fit the noise.\n\nL1, L2 and dropout are three different mechanisms for landing near this point without hand-tuning the model's size directly."}, "train-curve-b": {"d": "Training error as a function of training time (epochs), right panel.\n\nIt keeps falling the longer training runs — on the axis where early stopping actually operates, which is why early stopping cannot be marked on the left panel's complexity axis."}, "val-curve-b": {"d": "Validation error as a function of training epochs.\n\nIt falls with the training error at first, then turns upward once the model starts memorising training-specific noise: the same U-shape as the left panel, but against time spent training rather than model size."}, "earlyStop": {"d": "The training-time cutoff early stopping applies: training halts at the epoch where validation error is about to turn upward.\n\nIt is read directly off this chart, which is why early stopping needs a validation set held out from training in the first place."}}, "edges": {"naive-fit>regularized-fit": {"d": "What L1, L2 and dropout each do to an over-fit model: pull it back toward lower effective complexity without necessarily changing the number of parameters it has."}}, "walk": ["train-curve", "val-curve", "naive-fit", "regularized-fit", "train-curve-b", "val-curve-b", "earlyStop"]},
  "cache": {"nodes": {"user-turn": {"d": "A user's message or turn in the conversation that triggers a memory lookup."}, "cache": {"d": "A cache keyed by user and query, storing prior vector-search results so an identical or near-identical lookup can skip the underlying search.\n\nPopulation — filling it on a miss — is one code path. Invalidation — removing what is now wrong — has to happen from every code path that changes the underlying data. That asymmetry is the point of this figure.", "links": [{"label": "Pattern: cache-aside", "url": "SYSTEM%20DESIGN.html#/patterns/scaling-reads/cache-aside"}]}, "vector-search": {"d": "The underlying similarity search over the user's stored memories, run only when the cache misses."}, "new-memory": {"d": "A new fact or memory the user adds mid-conversation."}, "store": {"d": "The durable store of the user's memories, updated whenever a new memory is written.", "links": [{"label": "Pattern: cache invalidation on write", "url": "SYSTEM%20DESIGN.html#/patterns/scaling-reads/invalidation"}]}}, "edges": {"user-turn>cache": {"d": "The turn's query is looked up in the cache first, before touching the underlying search."}, "cache>vector-search": {"d": "On a miss, the query falls through to the real vector search."}, "vector-search>cache": {"d": "The vector search's result populates the cache so the next identical query can skip the search."}, "new-memory>store": {"d": "The new memory is written to the durable store."}, "store>cache": {"d": "The store's write must also invalidate this user's cached results — the edge that is easy to forget because the cache is invisible from the write path's code."}}, "walk": ["user-turn", "user-turn>cache", "cache", "cache>vector-search", "vector-search", "vector-search>cache", "new-memory", "new-memory>store", "store", "store>cache"]},
  "chain": {"nodes": {"x": {"d": "The input to the network, the value everything downstream is computed from.\n\nIt is also the variable the backward pass at the far left ultimately produces a gradient for, ∂loss/∂x."}, "f1": {"d": "The first layer in the composition, a function applied to x.\n\nDuring the forward pass it remembers its own input (part of the \"tape\") so that, on the backward pass, it can compute its local derivative ∂f1/∂x without recomputing anything.", "links": [{"label": "TrenTorch module source: layers", "url": "https://github.com/TrenTorch/TrenTorch/tree/main/data/src/03_layers"}]}, "f2": {"d": "The second layer, applied to f1's output.\n\nLike every layer here it is just a function; the network as a whole is the composition f3(f2(f1(x))), and the chain rule is the calculus rule for differentiating exactly that shape."}, "f3": {"d": "The third layer, whose output feeds the loss.\n\nIts local derivative ∂f3/∂f2 is the first term multiplied in during backpropagation, since the backward pass starts at the loss and works right to left.", "links": [{"label": "TrenTorch module source: autograd", "url": "https://github.com/TrenTorch/TrenTorch/tree/main/data/src/06_autograd"}]}, "loss": {"d": "The scalar the whole network is trained to minimise.\n\nBackpropagation starts here with ∂loss/∂loss = 1 and multiplies local derivatives leftward through f3, f2, f1 to reach ∂loss/∂x.", "links": [{"label": "Session: derivatives, properly", "url": "index.html#/s/2/2"}, {"label": "AI Engineering from Scratch: chain rule and autodiff", "url": "https://github.com/rohitg00/ai-engineering-from-scratch/tree/main/phases/01-math-foundations/05-chain-rule-and-autodiff"}]}}, "edges": {"x>f1": {"d": "Forward pass: x is consumed by the first layer, which also records x for later."}, "f1>f2": {"d": "f1's output becomes f2's input, forward."}, "f2>f3": {"d": "f2's output becomes f3's input, forward."}, "f3>loss": {"d": "f3's output is compared against a target to produce the scalar loss."}, "loss>f3": {"d": "Backward: the gradient of the loss with respect to itself (1) is multiplied by the local derivative ∂loss/∂f3."}, "f3>f2": {"d": "Backward: the running gradient is multiplied by f3's local derivative ∂f3/∂f2."}, "f2>f1": {"d": "Backward: the running gradient is multiplied by f2's local derivative ∂f2/∂f1."}, "f1>x": {"d": "Backward: the running gradient is multiplied by f1's local derivative ∂f1/∂x, giving the final ∂loss/∂x."}}, "walk": ["x", "x>f1", "f1", "f1>f2", "f2", "f2>f3", "f3", "f3>loss", "loss", "loss>f3", "f3>f2", "f2>f1", "f1>x"]},
  "completeness": {"nodes": {"snapshot": {"d": "The test fixture: a database seeded with a known set of financial events for the time window under test.\n\nBecause the fixture was built by hand, the count of events in that window is ground truth, not something the test has to guess at."}, "agent-s-ledger": {"d": "The financial ledger the agent under test actually produced from that same window.\n\nIt can look completely well-formed — clean formatting, plausible numbers — while still being wrong in a way formatting checks can't catch."}, "assert-every-event-appears": {"d": "The test assertion: every financial event known to exist in the snapshot must appear somewhere in the agent's ledger.\n\nThis only works because the answer is enumerable — the true count can be read straight from the fixture. A test that instead pins one expected output string can only check an answer's shape, never its completeness.", "links": [{"label": "Technique: monitoring as a completeness check", "url": "SYSTEM%20DESIGN.html#/patterns/reliability/monitoring"}, {"label": "Snapshot tests vs. behaviour-checking tests, the trade-offs", "url": "https://www.sitepen.com/blog/snapshot-testing-benefits-and-drawbacks"}]}, "fails": {"d": "The result when the ledger is missing entries the snapshot proves should be there — two refunds, in this case.\n\nThis is exactly the kind of gap a pinned-answer test misses, since a ledger missing two refunds can still look correctly formatted."}}, "edges": {"snapshot>assert-every-event-appears": {"d": "The known count from the fixture becomes the assertion's target."}, "agent-s-ledger>assert-every-event-appears": {"d": "The agent's actual output is checked against that target."}, "assert-every-event-appears>fails": {"d": "The count comes up short, so the test fails with a concrete, named gap instead of a vague mismatch."}}, "walk": ["snapshot", "agent-s-ledger", "snapshot>assert-every-event-appears", "agent-s-ledger>assert-every-event-appears", "assert-every-event-appears", "assert-every-event-appears>fails", "fails"]},
  "definerGrant": {"nodes": {"any-signed-in-user": {"d": "Any authenticated user of the application, regardless of which rows belong to them.\n\nThis is the actual caller PUBLIC includes — not an admin, not the app's own service role, just anyone logged in.", "links": [{"label": "Postgres docs: ALTER DEFAULT PRIVILEGES and the PUBLIC grant", "url": "https://www.postgresql.org/docs/current/sql-alterdefaultprivileges.html"}]}, "security-definer-function": {"d": "A Postgres function marked SECURITY DEFINER, so it runs with the privileges of the user who created it rather than the user who calls it.\n\nThat is exactly why it exists: some legitimate jobs — an aggregate across users, a system report — need to see past row-level security, and SECURITY DEFINER grants that without turning RLS off entirely.", "links": [{"label": "Postgres docs: writing SECURITY DEFINER functions safely", "url": "https://www.postgresql.org/docs/current/sql-createfunction.html"}]}, "every-user-s-rows": {"d": "Every row in the table the function reads, across every user, not just the caller's own.\n\nRow-level security is what normally stops one user's query from seeing this; a SECURITY DEFINER function bypasses it by design."}, "revoke-grant": {"d": "The fix, and its test: revoke the default PUBLIC grant, give EXECUTE only to the one role that needs it, and add a check that no other SECURITY DEFINER function has been left with a PUBLIC grant.\n\nFixing the one function is not enough, since the same default applies to every function created the same way — the durable fix is a rule, not a one-off patch.", "links": [{"label": "Supabase docs: row-level security and security definer functions", "url": "https://supabase.com/docs/guides/database/postgres/row-level-security"}, {"label": "Technique: least privilege failing by default", "url": "SYSTEM%20DESIGN.html#/patterns/agent-safety/least-privilege"}]}}, "edges": {"any-signed-in-user>security-definer-function": {"d": "Postgres grants EXECUTE on a new function to PUBLIC by default, so any authenticated caller can invoke it."}, "security-definer-function>every-user-s-rows": {"d": "Because the function runs as its owner, it can read rows row-level security would otherwise hide from the caller."}}, "walk": ["any-signed-in-user", "any-signed-in-user>security-definer-function", "security-definer-function", "security-definer-function>every-user-s-rows", "every-user-s-rows", "revoke-grant"]},
  "descent": {"nodes": {"loss-curve": {"d": "The loss surface along one direction in parameter space, the thing gradient descent is trying to walk downhill on.\n\nIts slope at any point is the gradient; descent always moves opposite that slope, which is why the update subtracts the gradient rather than adding it.", "links": [{"label": "Session: gradients and descent", "url": "index.html#/s/4/2"}]}, "minimum": {"d": "The lowest point of the loss curve shown, where the gradient is zero.\n\nGetting near it is the goal of every step; how cleanly a run approaches it depends entirely on the learning rate."}, "small-eta-path": {"d": "A sequence of steps taken with a small learning rate η.\n\nEach step is η times the local gradient, so the steps shrink as the curve flattens near the minimum, and the path converges smoothly without crossing to the other side.", "links": [{"label": "AI Engineering from Scratch: optimization", "url": "https://github.com/rohitg00/ai-engineering-from-scratch/tree/main/phases/01-math-foundations/08-optimization"}]}, "large-eta-path": {"d": "A sequence of steps taken with a learning rate too large for this curve.\n\nEach step overshoots the minimum and lands on the opposite slope, so the path bounces back and forth instead of settling — the textbook symptom that motivates learning-rate schedules and warmup.", "links": [{"label": "TrenTorch module source: optimizers", "url": "https://github.com/TrenTorch/TrenTorch/tree/main/data/src/07_optimizers"}]}}, "edges": {}, "walk": ["loss-curve", "minimum", "small-eta-path", "large-eta-path"]},
  "eigen": {"nodes": {"v-ordinary": {"d": "An ordinary vector v, arbitrary with respect to the transformation A.\n\nMost vectors are like this one: there is nothing special about the line they sit on.", "links": [{"label": "Session: vectors and matrices", "url": "index.html#/s/3/2"}]}, "av-ordinary": {"d": "The result of applying A to v: Av.\n\nIt lands off v's original line, at a different angle — the transformation has turned it, not just scaled it."}, "v-eigen": {"d": "An eigenvector of A: one of the special vectors whose direction A leaves unchanged.\n\nA can still change its length, but never rotates it off its own line — that is the entire, purely geometric definition.", "links": [{"label": "AI Engineering from Scratch: linear algebra intuition", "url": "https://github.com/rohitg00/ai-engineering-from-scratch/tree/main/phases/01-math-foundations/01-linear-algebra-intuition"}]}, "av-eigen": {"d": "The result of applying A to the eigenvector: Av = λv.\n\nIt lands on the exact same line as v, only longer or shorter by the eigenvalue λ. For A = [[2,0],[0,3]] and v = (1,0), Av = (2,0) = 2v, so λ = 2 here."}}, "edges": {}, "walk": ["v-ordinary", "av-ordinary", "v-eigen", "av-eigen"]},
  "embed": {"nodes": {"init-embeddings": {"d": "The embedding table right after initialisation: one row of random numbers per token.\n\nAt this point a row for \"cat\" and a row for \"run\" are equally arbitrary — nothing in the numbers yet reflects meaning.", "links": [{"label": "Session: embeddings and attention, at mechanism level", "url": "index.html#/s/4/3"}]}, "trained-embeddings": {"d": "The same table after training on some task.\n\nRows for tokens that behave alike in that task — here, cat and dog cluster, car and run cluster — have drifted toward each other, purely because gradient descent on the objective rewarded it.", "links": [{"label": "Jay Alammar: the illustrated word2vec", "url": "https://jalammar.github.io/illustrated-word2vec/"}, {"label": "TrenTorch module source: embeddings", "url": "https://github.com/TrenTorch/TrenTorch/tree/main/data/src/11_embeddings"}]}}, "edges": {"init-embeddings>trained-embeddings": {"d": "Gradient descent updates every row that participates in the loss, pulling rows used alike closer together over many steps of training."}}, "walk": ["init-embeddings", "init-embeddings>trained-embeddings", "trained-embeddings"]},
  "forkReplay": {"nodes": {"recorded-session": {"d": "The original session used as the fixed reference point for this comparison.\n\nBoth the baseline and the fork start from exactly the same recording, which is what makes a later difference between them meaningful."}, "baseline-replay": {"d": "A replay that answers every tool call from the recorded history, changing nothing.\n\nBecause nothing is overridden, this run should closely reproduce the recorded session; if it doesn't, the replay mechanism itself is broken, not the change being tested."}, "fork": {"d": "A replay identical to the baseline except for one deliberate override — a different prompt, or a different model.\n\nKeeping everything else fixed is what lets any difference in outcome be attributed specifically to that one change."}, "evaluators": {"d": "The same scoring logic applied to both the baseline's and the fork's transcripts.\n\nUsing identical evaluators on both runs is what makes their scores comparable at all."}, "verdict": {"d": "The comparison's conclusion: whether the one override made things better, worse, or made no measurable difference.", "links": [{"label": "Technique: eval suites as release gates", "url": "SYSTEM%20DESIGN.html#/patterns/grounding/eval-gate"}]}}, "edges": {"recorded-session>baseline-replay": {"d": "The baseline replay is built by answering every tool call from this recording."}, "recorded-session>fork": {"d": "The fork starts from the same recording, with one input overridden."}, "baseline-replay>evaluators": {"d": "The baseline's transcript is scored."}, "fork>evaluators": {"d": "The fork's transcript is scored the same way."}, "evaluators>verdict": {"d": "The two scores are compared to produce a verdict."}}, "walk": ["recorded-session", "recorded-session>baseline-replay", "baseline-replay", "recorded-session>fork", "fork", "baseline-replay>evaluators", "fork>evaluators", "evaluators", "evaluators>verdict", "verdict"]},
  "gradientVector": {"nodes": {"contours": {"d": "Contour lines of a loss surface over two parameters θ₁ and θ₂, viewed from above — each ring is a set of points with equal loss.\n\nRings closer together mean the surface is steeper there; the surface flattens out as the rings space out near the centre."}, "minimum": {"d": "The point of lowest loss on this surface, at the centre of the contours.\n\nGradient descent's whole job is to walk toward this point without ever seeing the surface directly, using only the local slope at wherever it currently stands."}, "theta": {"d": "The model's current parameter setting, θ, sitting partway up the loss surface.\n\nEvery training step moves this point a little. Where it moves to depends only on the gradient measured right here, not on the shape of the surface anywhere else."}}, "edges": {"theta>ascent": {"d": "∇L, the gradient at θ: every partial derivative, ∂L/∂θ₁ and ∂L/∂θ₂, collected into one vector. It points in the direction the loss increases fastest from this exact point."}, "theta>minimum": {"d": "−∇L, the negative gradient: the same vector, reversed — the direction of steepest decrease. Gradient descent steps this way, scaled by the learning rate."}}, "walk": ["contours", "theta", "theta>ascent", "theta>minimum", "minimum"]},
  "graphDiffYearOverYear": {"nodes": {"y1intake": {"d": "The walkthrough's first step in year 1: intake. It does not change in year 2.\n\nIt exists in the diagram mainly as a control — a step that stayed the same, so the reader can see the other three changes stand out by contrast."}, "y1review": {"d": "The review step as it worked in year 1: automated, no named individual involved.\n\nSome code or system performed this check without a human in the loop."}, "y1approve": {"d": "The named approver in year 1: Alex.\n\nApprovers are exactly the kind of detail that changes yearly, and that an auditor needs surfaced automatically rather than rediscovered by asking the client again."}, "y1system": {"d": "The downstream system of record in year 1: Oracle.\n\nA process step's system of record is part of the control environment. Swapping it can change what evidence looks like even if the process itself is described the same way."}, "y2intake": {"d": "The same intake step, one year later, unchanged.\n\nMatching this node to y1intake by position and label is what lets the diff treat it as 'no change' rather than flag it."}, "y2review": {"d": "The review step in year 2: now done manually, by a person, where it used to be automated.\n\nThis is a real control change — a manual step has different failure modes (fatigue, inconsistency) than an automated one, and an auditor needs to know it happened."}, "y2approve": {"d": "The named approver in year 2: Priya, replacing Alex.\n\nA changed approver is one of the first things an auditor checks, since it can signal a change in authority or a personnel transition worth understanding."}, "y2system": {"d": "The downstream system of record in year 2: SAP, replacing Oracle.\n\nA system swap often changes data formats, retention and access controls even when the business process is described identically. It is never a purely cosmetic change."}}, "edges": {"y1intake>y1review": {"d": "The year-1 process flow, step to step, before any evidence about actors or systems is attached."}, "y1review>y1approve": {"d": "The year-1 flow continues from the (automated) review into the named approver."}, "y1approve>y1system": {"d": "The year-1 flow ends at the system of record, Oracle."}, "y2intake>y2review": {"d": "The year-2 process flow, structurally identical in shape to year 1."}, "y2review>y2approve": {"d": "The year-2 flow from the (now manual) review into the new approver, Priya."}, "y2approve>y2system": {"d": "The year-2 flow ends at the new system of record, SAP."}}, "walk": ["y1intake", "y1review", "y1approve", "y1system", "y2intake", "y2review", "y2approve", "y2system"]},
  "harnessSeam": {"nodes": {"agent": {"d": "The AI agent under test, issuing a tool call the same way it would against production.\n\nFrom the agent's point of view nothing about the call looks different whether the run is being recorded, replayed, or executed live."}, "tool-body-runs-for-real": {"d": "The tool's own implementation code: ranking, filtering, shaping a raw response into what the model actually sees.\n\nThis code runs for real in every replay, because most of the bugs worth catching live in this seam between a provider's raw response and what the model is given. Mocking this layer would hide exactly the logic being tested.", "links": [{"label": "Technique: shadow mode and online production signals", "url": "SYSTEM%20DESIGN.html#/patterns/grounding/shadow-online"}]}, "provider-boundary": {"d": "The single point where the tool's code calls out to an external service, gated by a harness flag.\n\nThis is the only place a replay diverts anything at all — everything upstream of it is untouched production code.", "links": [{"label": "Technique: environment snapshots at the provider boundary", "url": "SYSTEM%20DESIGN.html#/patterns/agent-durability/env-snapshots"}]}, "gmail-calendar": {"d": "The real Gmail or calendar API, used only when the harness flag is off — that is, in production. The dashed border marks it as unreachable during a replay."}, "sqlite-snapshot": {"d": "A per-case SQLite database that answers provider calls in the exact shape Gmail or the calendar API would, when the harness flag is on.\n\nBecause it returns data in the provider's own response shape, the tool code upstream cannot tell the difference and keeps behaving exactly as it does in production."}}, "edges": {"agent>tool-body-runs-for-real": {"d": "The agent's tool call enters real, unmocked tool code."}, "tool-body-runs-for-real>provider-boundary": {"d": "After ranking and shaping, the only step left is the actual network call, which is where the harness intervenes."}, "provider-boundary>gmail-calendar": {"d": "In production, with the harness flag off, the call reaches the real API."}, "provider-boundary>sqlite-snapshot": {"d": "In a replay, with the harness flag on, the call is redirected to the case's snapshot instead."}}, "walk": ["agent", "agent>tool-body-runs-for-real", "tool-body-runs-for-real", "tool-body-runs-for-real>provider-boundary", "provider-boundary", "provider-boundary>gmail-calendar", "gmail-calendar", "provider-boundary>sqlite-snapshot", "sqlite-snapshot"]},
  "hybridRetrieval": {"nodes": {"query": {"d": "The user's or agent's search query, before any retrieval happens.\n\nThe same query is sent down two independent paths, lexical and dense, because neither is good at everything a query might need."}, "lexical": {"d": "Lexical search: exact term matching, via BM25 or Postgres full-text search (pg_fts).\n\nIt is exact — it finds an invoice number, a date or a product code because the token itself matches — which is exactly what dense embeddings are weak at.", "links": [{"label": "Pattern: Postgres full-text search", "url": "SYSTEM%20DESIGN.html#/patterns/search/pg-fts"}]}, "dense": {"d": "Dense retrieval: nearest-neighbour search over embedding vectors.\n\nIt is good at matching on meaning and paraphrase even when no exact term overlaps, and correspondingly bad at exact tokens like amounts, invoice numbers or dates, which look like arbitrary points in embedding space.", "links": [{"label": "Pattern: vector search", "url": "SYSTEM%20DESIGN.html#/patterns/search/vector"}]}, "merge": {"d": "The step that combines the lexical and dense candidate sets into one pool before ranking.\n\nA document that both methods surfaced independently is a stronger signal than one only lexical or only dense found."}, "rerank": {"d": "A model that reorders the merged candidates by relevance to the query, using richer signal than either retrieval method's own score alone.\n\nRetrieval's job is to get the right documents into a small candidate set cheaply; reranking's job is to get the ordering right within that set.", "links": [{"label": "Pattern: hybrid search with a rerank stage", "url": "SYSTEM%20DESIGN.html#/patterns/search/hybrid-rerank"}]}, "topk": {"d": "The final k documents kept after reranking, handed to whatever consumes them next: an LLM's context window, a citation step.\n\nk is chosen to balance coverage against cost and context size, not to be as large as possible.", "links": [{"label": "Pattern: choosing top-k", "url": "SYSTEM%20DESIGN.html#/patterns/search/topk"}]}}, "edges": {"query>lexical": {"d": "The same query text, sent to the lexical index unchanged."}, "query>dense": {"d": "The query, embedded into the same vector space as the indexed documents, sent to the dense index."}, "lexical>merge": {"d": "The lexical candidate set: documents whose text matched, in whatever order lexical scoring produced."}, "dense>merge": {"d": "The dense candidate set: documents whose embeddings landed nearest the query's, independent of lexical overlap."}, "merge>rerank": {"d": "The combined candidate pool, deduplicated, in no particular final order yet."}, "rerank>topk": {"d": "The reranked list, truncated to the top k — everything below the cut is discarded."}}, "walk": ["query", "query>lexical", "lexical", "query>dense", "dense", "lexical>merge", "dense>merge", "merge", "merge>rerank", "rerank", "rerank>topk", "topk"]},
  "kitaruFreeze": {"nodes": {"k-agent-call": {"d": "The agent making a tool call during a Kitaru replay."}, "k-lookup": {"d": "Kitaru's replay mechanism: hash the tool name and arguments with SHA-256 and look up that exact hash in the recorded call log.\n\nThe tool's actual body never runs at all during a replay; the call is answered purely by lookup."}, "k-call-log": {"d": "The recording: one row per tool call actually observed during the original session, keyed by the exact hash of its arguments.\n\nBecause the key is an exact hash, there is no fuzzy or partial matching — the arguments have to match byte-for-byte after canonical JSON serialization."}, "k-miss": {"d": "What happens when the agent asks something the recording never saw: no row exists for that hash.\n\nThe configured on_miss policy decides what happens next: kill the run, hand the model a literal error result and keep going, or — least safely — fall through to calling production for real."}, "h-agent-call": {"d": "The agent making a tool call during a replay run under Pranav's own harness."}, "h-tool-logic": {"d": "The tool's actual implementation code, which runs for real in every replay.\n\nIt queries the snapshot database rather than looking anything up by a recorded key — the difference between a query and a lookup is the whole point of this approach."}, "h-snapshot": {"d": "A per-case SQLite or Postgres-template database seeded with the scenario under test and enough surrounding, redacted data to make it coherent.\n\nA concrete example: a snapshot with two or three contacts all named Mike, deliberately included so the agent has to disambiguate rather than being handed the answer.", "links": [{"label": "Technique: environment snapshots, the frozen world", "url": "SYSTEM%20DESIGN.html#/patterns/agent-durability/env-snapshots"}, {"label": "Hamel Husain: your AI product needs evals", "url": "https://hamel.dev/blog/posts/evals/index.html"}]}, "h-no-miss": {"d": "The structural consequence: there is no such thing as a miss in this approach.\n\nBecause the whole world is frozen, not just a sequence of expected calls, the agent can take a path it never took during recording and still get a truthful, internally consistent answer back.", "links": [{"label": "Technique: eval suites as release gates", "url": "SYSTEM%20DESIGN.html#/patterns/grounding/eval-gate"}]}}, "edges": {"k-agent-call>k-lookup": {"d": "The call's name and arguments are hashed and checked against the recording."}, "k-lookup>k-call-log": {"d": "The hash lookup runs against the recorded call log."}, "k-call-log>k-miss": {"d": "When the agent asks something new — no matching hash exists — it is a miss instead of a hit."}, "h-agent-call>h-tool-logic": {"d": "The call reaches the tool's real implementation code."}, "h-tool-logic>h-snapshot": {"d": "The tool code queries the snapshot database to answer the call."}, "h-snapshot>h-no-miss": {"d": "Because the snapshot answers any coherent query, not just previously recorded ones, there is no miss case to handle."}}, "walk": ["k-agent-call", "k-agent-call>k-lookup", "k-lookup", "k-lookup>k-call-log", "k-call-log", "k-call-log>k-miss", "k-miss", "h-agent-call", "h-agent-call>h-tool-logic", "h-tool-logic", "h-tool-logic>h-snapshot", "h-snapshot", "h-snapshot>h-no-miss", "h-no-miss"]},
  "kitaruOrder": {"nodes": {"base-call-1": {"d": "The first of three identical tool calls, replayed under baseline scope.\n\nBaseline is the only one of the three replay scopes that consumes recorded results in order rather than always returning the same one."}, "base-result-a": {"d": "The first recorded result for this cache key, consumed by the first call under baseline's ordered lookup, at occurrence 0."}, "base-call-2": {"d": "The second identical call. Under baseline scope the client's occurrence counter has already advanced, so this call gets the next result in sequence instead of repeating the first."}, "base-result-b": {"d": "The second recorded result, consumed at occurrence 1."}, "base-call-3": {"d": "The third identical call, consuming the third recorded result at occurrence 2."}, "base-result-c": {"d": "The third recorded result. Once occurrence exceeds however many results were recorded for this key, the next identical call would miss."}, "scoped-call-1": {"d": "The same first call, this time replayed under agent or cohort_version scope instead of baseline."}, "scoped-call-2": {"d": "The same second call, under agent or cohort_version scope."}, "scoped-call-3": {"d": "The same third call, under agent or cohort_version scope."}, "newest-result": {"d": "The single most-recently-recorded result for this cache key.\n\nUnder agent or cohort_version scope, occurrence is forced to None and the counter is never incremented, so every one of the three calls — no matter how many times it repeats — gets this exact same row, forever.", "links": [{"label": "Technique: atomic counters vs. a race on an unguarded read-modify-write", "url": "SYSTEM%20DESIGN.html#/patterns/contention/atomic"}]}, "concurrency-race": {"d": "A real defect in the occurrence counter, found by reading the source rather than by observing a failure.\n\nThe sequence is: read counter, then await the tool lookup, then write counter back — and the increment happens on the far side of that await, on a plain unguarded dictionary. Two identical tool calls in flight at once can both read occurrence 0 before either writes it back, so both get result A, and result B is silently never consumed."}}, "edges": {"base-call-1>base-result-a": {"d": "occurrence=0: the first call consumes the first recorded result."}, "base-call-2>base-result-b": {"d": "occurrence=1: the counter advanced, so this call consumes the second result."}, "base-call-3>base-result-c": {"d": "occurrence=2: the third call consumes the third result."}, "scoped-call-1>newest-result": {"d": "Occurrence is forced to None under this scope, so this call resolves to the single newest row."}, "scoped-call-2>newest-result": {"d": "The counter never advances, so this call resolves to the same newest row as the others."}, "scoped-call-3>newest-result": {"d": "Same again: every call under this scope converges on the one newest row."}}, "walk": ["base-call-1", "base-call-1>base-result-a", "base-result-a", "base-call-2", "base-call-2>base-result-b", "base-result-b", "base-call-3", "base-call-3>base-result-c", "base-result-c", "scoped-call-1", "scoped-call-1>newest-result", "scoped-call-2", "scoped-call-2>newest-result", "scoped-call-3", "scoped-call-3>newest-result", "newest-result", "concurrency-race"]},
  "kitaruPlanes": {"nodes": {"kitaru-server": {"d": "Kitaru's control-plane API: FastAPI, backed by Postgres and a blob store, that hands out task specs, leases and tokens.\n\nIt executes no user code, ever — that specific claim holds up against the source. Everything that actually runs an agent happens elsewhere, in the user's own environment.", "links": [{"label": "Control plane and data plane, explained", "url": "https://konghq.com/blog/learning-center/control-plane-vs-data-plane"}]}, "postgres": {"d": "The database holding every record Kitaru keeps: sessions, session nodes (the trace tree), cache keys, and everything the replay lookup runs against.\n\nThe cache_key column is indexed here, since it is the join key every tool-call replay looks up by."}, "blob-store": {"d": "Object storage for larger payloads: plugin code and trace data too big to fit comfortably in a Postgres row."}, "worker": {"d": "A process that runs inside the user's own environment — their venv, their credentials, their network — and does the actual work Kitaru's server only coordinates.\n\nIt polls the server in a claim loop, sends heartbeats, and spawns and kills the subprocesses that do the real work.", "links": [{"label": "Technique: worker leases for a polling claim loop", "url": "SYSTEM%20DESIGN.html#/patterns/agent-durability/worker-leases"}]}, "agent-subprocess": {"d": "The agent under test, spawned as an ordinary OS subprocess running its registered command verbatim, in its working directory, with the inherited environment and credentials.\n\nThere is no sandbox around it: isolation is limited to the process tree, a timeout, and a kill on teardown. That is the entire isolation model.", "links": [{"label": "Temporal: workflow execution, event history and replay", "url": "https://docs.temporal.io/workflow-execution"}]}, "evaluator-subprocess": {"d": "A separate subprocess that scores a completed run, spawned with its own isolated environment via uv so its dependencies don't collide with the agent's."}, "importer-subprocess": {"d": "A separate subprocess that imports existing session data — turning an existing trace into something Kitaru can replay — also isolated via its own uv environment."}, "model-provider": {"d": "The actual LLM API — OpenAI, Anthropic, or whichever the agent is configured to call.\n\nThis call is never replayed. Even inside a replay run, the agent subprocess calls the real model provider live, every time; only the tool-call side gets intercepted."}}, "edges": {"kitaru-server>worker": {"d": "The worker polls the server's claim loop for tasks to run."}, "worker>agent-subprocess": {"d": "The worker spawns the agent as a subprocess to do the actual run."}, "worker>evaluator-subprocess": {"d": "The worker spawns an evaluator subprocess to score a completed run."}, "worker>importer-subprocess": {"d": "The worker spawns an importer subprocess to bring in existing session data."}, "agent-subprocess>model-provider": {"d": "The agent calls the real model provider directly and live; this call is never intercepted or replayed."}, "agent-subprocess>kitaru-server": {"d": "Per tool call, the in-process adapter posts back to the server's tool-lookup endpoint and writes the resulting trace node."}}, "walk": ["kitaru-server", "postgres", "blob-store", "worker", "kitaru-server>worker", "worker>agent-subprocess", "agent-subprocess", "worker>evaluator-subprocess", "evaluator-subprocess", "worker>importer-subprocess", "importer-subprocess", "agent-subprocess>model-provider", "model-provider", "agent-subprocess>kitaru-server"]},
  "kitaruPosition": {"nodes": {"mar-2026-pivot-1": {"d": "The first pivot: ZenML launched Kitaru in March 2026, positioned as a durable-execution runtime.\n\nThe framing at this point was workflow orchestration with checkpointing, aimed at the same space as Temporal or Inngest.", "links": [{"label": "ZenML blog: the Kitaru launch", "url": "https://www.zenml.io/blog/kitaru-launch"}, {"label": "ZenML docs: stacks and stack components", "url": "https://docs.zenml.io/concepts/stack_components"}]}, "apr-jul-2026": {"d": "The months following the first pivot, during which Kitaru's content kept making the durable-execution comparison.\n\nBlog posts from this window compare Kitaru against Temporal, Inngest and Trigger.dev — direct competitors in workflow orchestration, not in evals."}, "aug-18-2026-pivot-2": {"d": "The second pivot: on August 18, 2026, Kitaru repositioned around replay-based evals instead of durable execution.\n\nThe product's own vocabulary changed with it — \"Workers\" replacing \"Stacks\" as the term for its execution unit — and this relaunch was never posted to Hacker News, unlike the original launch."}, "sep-2026": {"d": "The month after the second pivot, by which point Kitaru was still actively shipping.\n\nA coding-agent sandbox research post from this period shows the pivot wasn't a one-off announcement — the product kept moving in the new direction."}, "comparison-content-switches": {"d": "Independent evidence the pivot was real: which competitors the blog's own comparison posts name.\n\nBefore August 18 those posts argue against durable-execution tools (Temporal, Inngest); afterward, the same kind of post argues against eval and observability vendors instead (Braintrust, Arize) — the content followed the positioning, not the other way around."}}, "edges": {"mar-2026-pivot-1>apr-jul-2026": {"d": "The durable-execution framing continues for several months after the initial launch."}, "apr-jul-2026>aug-18-2026-pivot-2": {"d": "That framing ends abruptly on August 18, 2026, when the second pivot lands."}, "aug-18-2026-pivot-2>sep-2026": {"d": "The new positioning continues into September with further shipped work."}, "aug-18-2026-pivot-2>comparison-content-switches": {"d": "The clearest evidence for the pivot: the blog's own competitor comparisons switch targets at the same moment."}}, "walk": ["mar-2026-pivot-1", "mar-2026-pivot-1>apr-jul-2026", "apr-jul-2026", "apr-jul-2026>aug-18-2026-pivot-2", "aug-18-2026-pivot-2", "aug-18-2026-pivot-2>sep-2026", "sep-2026", "aug-18-2026-pivot-2>comparison-content-switches", "comparison-content-switches"]},
  "kitaruReplay": {"nodes": {"build-process-env": {"d": "The worker's first step before spawning the agent: build the child process's environment variables.\n\nIt starts from a full copy of the worker's own os.environ — inheriting everything — then layers on run-time overrides and secrets from Kitaru's secret store, and finally clears and resets Kitaru's own contract variables so nothing inherited leaks through by accident."}, "injected-into-child": {"d": "The small set of environment variables Kitaru actually injects into the spawned agent process.\n\nKITARU_REPLAY_ID is the one that matters most — its presence is the entire replay trigger. If it is absent, the run is treated as an ordinary recording, not a replay."}, "platform-spawn": {"d": "The actual process spawn: the registered command, run verbatim, in its working directory.\n\nThe child gets the same filesystem, network access and credentials the worker process already had — there is no sandbox. Isolation is limited to the process tree itself, a timeout, and a kill_tree call on teardown; that is the complete list.", "links": [{"label": "What running a subprocess without a sandbox gives away", "url": "https://www.pandastack.ai/blog/how-to-sandbox-untrusted-code/"}, {"label": "Technique: least privilege, and what this deliberately skips", "url": "SYSTEM%20DESIGN.html#/patterns/agent-safety/least-privilege"}]}, "adapter-in-your-process": {"d": "A small library the agent imports, running inside the same process as the agent code.\n\nOn startup it reads KITARU_REPLAY_ID and, if present, fetches the override and tool policy for this replay over HTTP from the Kitaru server."}, "wrap-model-request-wrap-tool-execute": {"d": "Two capability hooks the adapter installs into the agent framework — PydanticAI in this example: one wraps model requests to apply overrides, the other wraps tool execution to apply the tool policy.\n\nThis is the interception point: the only place Kitaru's replay logic gets a chance to intervene in what the agent does."}, "not-every-call-is-hooked": {"d": "The fidelity gap this creates: interception only happens at the framework's own tool-call hook.\n\nAnything that reaches the outside world without going through a registered tool — a bare HTTP request, a direct database write — is invisible to Kitaru and simply happens for real, even during a replay.", "links": [{"label": "Technique: a policy gate, and where it can't reach", "url": "SYSTEM%20DESIGN.html#/patterns/agent-safety/policy-gate"}]}}, "edges": {"build-process-env>injected-into-child": {"d": "The finished environment, including the contract variables, is what actually gets passed to the child process."}, "injected-into-child>platform-spawn": {"d": "That environment is handed to the spawn call along with the command and working directory."}, "platform-spawn>adapter-in-your-process": {"d": "Once running, the agent process imports the adapter, which reads the injected variables."}, "adapter-in-your-process>wrap-model-request-wrap-tool-execute": {"d": "The adapter installs its hooks into the agent framework so it can intervene on every model request and tool call."}, "wrap-model-request-wrap-tool-execute>not-every-call-is-hooked": {"d": "But the hook only sees calls that go through the framework's own registered tool mechanism, leaving anything else unrouted and unreplayed."}}, "walk": ["build-process-env", "build-process-env>injected-into-child", "injected-into-child", "injected-into-child>platform-spawn", "platform-spawn", "platform-spawn>adapter-in-your-process", "adapter-in-your-process", "adapter-in-your-process>wrap-model-request-wrap-tool-execute", "wrap-model-request-wrap-tool-execute", "wrap-model-request-wrap-tool-execute>not-every-call-is-hooked", "not-every-call-is-hooked"]},
  "logs": {"nodes": {"product": {"d": "The product of many probabilities, one per independent event or token.\n\nEach factor is at most 1, so the product shrinks every time another one is multiplied in; after a few hundred terms it underflows to exactly 0.0 in floating point even though no single probability was ever zero. This is what a sequence likelihood looks like before anyone takes its log.", "links": [{"label": "Session: functions, exponentials, logarithms", "url": "index.html#/s/1/2"}]}, "logsum": {"d": "The same likelihood, rewritten as a sum of logarithms instead of a product of probabilities.\n\nA sum of numbers like -2, -3, -10 never underflows the way a product of small fractions does, and a sum is also what you actually differentiate when computing a gradient. log(ab) = log(a) + log(b) is the only algebra needed to justify the swap.", "links": [{"label": "AI Engineering from Scratch: information theory", "url": "https://github.com/rohitg00/ai-engineering-from-scratch/tree/main/phases/01-math-foundations/09-information-theory"}]}, "linear-plot": {"d": "An exponential curve, y = e^(kt), drawn on ordinary linear axes.\n\nIt bends because equal steps in time produce a growing absolute change; the last segment rises far more steeply than the first even though the growth rate k is constant throughout."}, "log-plot": {"d": "The identical growth process, drawn with a logarithmic y-axis instead.\n\nTaking the log turns a constant multiplicative rate into a constant additive rate, so the curve becomes a straight line whose slope is k. A straight line on a log plot is the visual signature of exponential growth on a linear one."}}, "edges": {"product>logsum": {"d": "Taking the log of both sides turns the product into a sum, term by term: log(p1 x p2 x ... x pn) = log p1 + log p2 + ... + log pn."}}, "walk": ["product", "product>logsum", "logsum", "linear-plot", "log-plot"]},
  "missFlow": {"nodes": {"replayed-call": {"d": "A tool call made during a replay run, in the same shape the original session made it.\n\nIt carries the same cache key the recording would have used, so it can be looked up."}, "look-up-by-key": {"d": "The lookup step: does a call with this exact key exist in the recording?\n\nMatching is exact only — there is no fuzzy matching — so any change to the call's shape produces a miss rather than a partial match.", "links": [{"label": "Technique: cache-aside, and what a miss means here", "url": "SYSTEM%20DESIGN.html#/patterns/scaling-reads/cache-aside"}, {"label": "VCR.py: how a request is matched to a recording", "url": "https://vcrpy.readthedocs.io/en/latest/configuration.html"}]}, "recorded-result": {"d": "The stored result from the original session, returned unchanged when the key matches — a hit."}, "diff": {"d": "A side-by-side comparison of the recorded call and what the new agent actually tried, shown to a person when the key doesn't match — a miss.\n\nThe miss itself is information: it means the agent's behaviour changed since the recording was made, not necessarily that anything is broken.", "links": [{"label": "VCR.py: record modes, what happens on a miss", "url": "https://vcrpy.readthedocs.io/en/latest/usage.html"}]}, "accept-as-equal": {"d": "A person's judgment that the new call is an equivalent variant of the recorded one, given as a single command.\n\nAccepting it writes a static alias mapping the new key to the old result, so the next replay hits automatically, and every accepted pair becomes a labelled example for anything automatic built later."}}, "edges": {"replayed-call>look-up-by-key": {"d": "The call's key is checked against the recording."}, "look-up-by-key>recorded-result": {"d": "On a hit, the recorded result is returned as-is."}, "look-up-by-key>diff": {"d": "On a miss, the recorded call and the new attempt are shown together instead of failing outright."}, "diff>accept-as-equal": {"d": "A person reviews the difference and decides whether the two calls mean the same thing."}, "accept-as-equal>recorded-result": {"d": "Accepting the variant writes an alias, so this same call hits the recorded result on the next run."}}, "walk": ["replayed-call", "replayed-call>look-up-by-key", "look-up-by-key", "look-up-by-key>recorded-result", "recorded-result", "look-up-by-key>diff", "diff", "diff>accept-as-equal", "accept-as-equal", "accept-as-equal>recorded-result"]},
  "multiturn": {"nodes": {"rec-u1": {"d": "The first user turn as it was actually recorded in the original session.\n\nIt is where every replay starts: the same opening line is fed to the agent whether the run is a faithful baseline or a fork that changes something.", "links": [{"label": "Technique: checkpointing a transcript turn by turn", "url": "SYSTEM%20DESIGN.html#/patterns/agent-durability/transcript-checkpoint"}]}, "rec-a1": {"d": "The agent's recorded reply to U1, part of the fixed transcript.\n\nA baseline replay that changes nothing should reproduce this turn closely; a fork is allowed to diverge from it."}, "rec-u2": {"d": "The second recorded user turn, written by the real person in reply to A1.\n\nIt only makes sense as an answer to that specific A1. If a fork's agent says something different at A1, this line stops fitting the conversation it was written for."}, "rec-a2": {"d": "The agent's recorded second reply, given in a conversation that has not yet diverged from what was recorded."}, "rec-u3": {"d": "The third recorded user turn, further along in the same unmodified conversation."}, "rec-a3": {"d": "The agent's recorded third and final reply in this transcript."}, "fork-u1": {"d": "The same opening user turn, replayed unchanged into the fork.\n\nBoth the baseline and the fork start identically, so anything that differs later can be attributed to the one thing the fork changed."}, "fork-a1": {"d": "The fork's reply to U1, marked with a prime because it can differ from the recorded A1.\n\nHere it does diverge — the fork's agent said something different — which is exactly the kind of change a fork replay exists to surface."}, "fork-u2": {"d": "The original recorded U2, tried unmodified against the diverged A1′.\n\nIt no longer fits: it was written as a reply to a specific A1 the fork's agent never actually said, so replaying it verbatim would put words in the user's mouth that don't follow from this conversation. The dashed border marks it as rejected, not played."}, "simulated-user": {"d": "A model standing in for the human user once the recorded transcript stops making sense.\n\nIt is conditioned on the goal extracted from the original session, not on the literal recorded lines, so it can react to whatever the agent actually said. It is calibrated first — run against the unchanged baseline and checked that it reproduces the recorded turns — and then held fixed across baseline and fork, so it behaves as a controlled variable rather than a second thing that changed.", "links": [{"label": "tau-bench: agent, tool, and a simulated user", "url": "https://arxiv.org/abs/2406.12045"}]}, "fork-u2p": {"d": "A new user turn generated by the simulated user, in direct response to A1′.\n\nUnlike the rejected recorded U2, this one is a coherent reply to what the agent actually said."}, "fork-a2p": {"d": "The agent's reply to the simulated U2′, continuing the forked conversation under simulation from here on."}}, "edges": {"fork-u2>simulated-user": {"d": "The recorded U2 is handed off once it no longer fits; the simulator takes over the user's side of the conversation from this point."}, "simulated-user>fork-u2p": {"d": "The simulator produces a new user turn conditioned on the goal and on A1′, not on the abandoned recorded line."}, "fork-u2p>fork-a2p": {"d": "The agent replies to the simulated turn like any other turn, and the forked conversation continues under simulation."}}, "walk": ["rec-u1", "rec-a1", "rec-u2", "rec-a2", "rec-u3", "rec-a3", "fork-u1", "fork-a1", "fork-u2", "fork-u2>simulated-user", "simulated-user", "simulated-user>fork-u2p", "fork-u2p", "fork-u2p>fork-a2p", "fork-a2p"]},
  "nyquist": {"nodes": {"true-signal": {"d": "The continuous, real-world sound-pressure wave before it is digitised.\n\nA microphone captures this continuously, but a computer can only store a finite list of numbers, which is why sampling has to happen at all.", "links": [{"label": "Session: sampling and Nyquist", "url": "index.html#/s/3/3"}]}, "samples": {"d": "The discrete readings actually stored: the wave's amplitude measured N times per second.\n\nEverything a digital system knows about the sound is contained in this list of numbers — nothing between samples is recorded.", "links": [{"label": "Alaap plan, stage 1: sound as data, sampling and Nyquist", "url": "ALAAP.html#/plan/stage-1"}]}, "below-nyquist": {"d": "Any frequency component at or below N/2, half the sampling rate.\n\nThese are represented correctly and can be perfectly reconstructed from the samples, which is the content of the sampling theorem."}, "above-nyquist": {"d": "Any frequency component above N/2.\n\nIt cannot be represented at this rate; it does not disappear, it aliases — folds back down and shows up disguised as a lower, incorrect frequency in the sampled data.", "links": [{"label": "AI Engineering from Scratch: audio fundamentals", "url": "https://github.com/rohitg00/ai-engineering-from-scratch/tree/main/phases/06-speech-and-audio/01-audio-fundamentals"}]}}, "edges": {}, "walk": ["true-signal", "samples", "below-nyquist", "above-nyquist"]},
  "nyquistBand": {"nodes": {"representable": {"d": "The band of frequencies, from 0 up to N/2, that a signal sampled at rate N can represent without ambiguity.\n\nAny true frequency inside this band is recorded faithfully. Nothing above it is."}, "aliased": {"d": "The band of frequencies above N/2 that cannot be represented directly at sample rate N.\n\nA true frequency in this region is not simply discarded: it is recorded as a false frequency that does fall inside the representable band. That folding is what aliasing means.", "links": [{"label": "Alaap: frequency, and how estimators lie", "url": "ALAAP.html#/plan/stage-11"}]}, "trueFreq": {"d": "An example true frequency at 0.6 times the sample rate N, above the Nyquist limit of 0.5N.\n\nSampled at rate N, this frequency cannot be told apart from a genuine lower frequency: the sampler has no way to know which one actually produced the signal."}, "aliasedFreq": {"d": "The false frequency, at 0.4N, that a true frequency of 0.6N is recorded as once sampled at rate N.\n\nNote the symmetry: 0.4N and 0.6N are mirror images around the Nyquist frequency 0.5N. Aliasing folds a frequency back around N/2, it does not scatter it randomly."}}, "edges": {"trueFreq>aliasedFreq": {"d": "The folding relationship itself: a true frequency above N/2 is recorded as its mirror image below N/2 — not lost, and not left where it was."}}, "walk": ["representable", "aliased", "trueFreq", "trueFreq>aliasedFreq", "aliasedFreq"]},
  "overfit": {"nodes": {"training-curve": {"d": "Training loss over epochs: the error measured on the exact data the model is being fit to.\n\nIt keeps falling for as long as the model has capacity left to exploit, whether that capacity is being used to learn general structure or to memorise the training set outright — the curve alone cannot tell you which.", "links": [{"label": "Session: overfitting, by mechanism", "url": "index.html#/s/2/3"}]}, "validation-curve": {"d": "Validation loss over epochs: the error measured on held-out data the model never trains on.\n\nIt falls alongside training loss at first, then turns upward once the model starts fitting noise specific to the training set rather than structure that generalises — that turn is the actual overfitting signal.", "links": [{"label": "AI Engineering from Scratch: bias-variance", "url": "https://github.com/rohitg00/ai-engineering-from-scratch/tree/main/phases/02-ml-fundamentals/10-bias-variance"}]}, "divergence-point": {"d": "The epoch where the two curves part ways: training loss keeps falling while validation loss turns up.\n\nThis is the diagnostic moment every anti-overfitting technique is built around — early stopping reads it directly off the chart and halts training here.", "links": [{"label": "Srivastava et al., Dropout: a simple way to prevent overfitting", "url": "https://jmlr.org/papers/v15/srivastava14a.html"}]}}, "edges": {}, "walk": ["training-curve", "validation-curve", "divergence-point"]},
  "oxusControl": {"nodes": {"control": {"d": "The written definition of the control being tested — for example, \"all purchase orders over $10k require two approvals.\" Everything below exists to test whether this held for the period.", "links": [{"label": "Session: an agent that tests a SOX control", "url": "index.html#/s/4/4"}]}, "population": {"d": "Every transaction the control's definition applies to, pulled by a query against the source system for the period under test."}, "sample": {"d": "A subset of the population selected for detailed testing, chosen by seeded code so the same run produces the same sample — required for the workpaper to be reproducible on review."}, "evidence": {"d": "The documents and records backing each sampled item, broken into individually addressable chunks (E1..En) that the model can cite by handle rather than by copying text."}, "attribute-test": {"d": "The model reads evidence only through these opaque handles and, for every attribute it tests — was it approved, by whom, was the amount within policy — must cite the specific handle that supports its answer.", "links": [{"label": "Pattern: forcing every claim to cite its source", "url": "SYSTEM%20DESIGN.html#/patterns/grounding/citations"}]}, "verify": {"d": "Deterministic code that checks a cited handle's underlying span actually contains the value the model claimed. If it does not, the result fails closed rather than being trusted."}, "exceptions": {"d": "Instances where a sampled item failed its attribute test, computed by code directly from attribute-test results — not written or judged by the model, so it cannot describe a real exception as \"effective.\""}, "draft": {"d": "The narrative workpaper text explaining the testing and its results — the one part of the pipeline the model is trusted to write, because the facts underneath it are already fixed by code."}, "reviewer": {"d": "The human who reads the draft, checks the cited evidence and the computed exceptions, and signs off on the control's conclusion."}}, "edges": {"control>population": {"d": "The control's definition determines which query pulls the population it applies to."}, "population>sample": {"d": "A seeded selection draws a reproducible sample from the full population."}, "sample>evidence": {"d": "Each sampled item's supporting documents are broken into citable evidence chunks."}, "evidence>attribute-test": {"d": "The model tests each required attribute against the evidence, citing a handle for every claim it makes."}, "attribute-test>verify": {"d": "Every citation the model makes is checked against the real span it points to before it is trusted."}, "verify>exceptions": {"d": "Attribute results that fail verification, or fail the test itself, become exceptions — computed by code, not asserted by the model."}, "verify>attribute-test": {"d": "When a citation does not hold up, verification fails closed and rejects that attribute test rather than letting an unverified claim through."}, "exceptions>draft": {"d": "The computed exceptions are handed to the model to narrate, not to decide."}, "draft>reviewer": {"d": "The narrative draft goes to a human reviewer, along with the evidence and exceptions it was built from."}}, "walk": ["control", "control>population", "population", "population>sample", "sample", "sample>evidence", "evidence", "evidence>attribute-test", "attribute-test", "attribute-test>verify", "verify", "verify>attribute-test", "verify>exceptions", "exceptions", "exceptions>draft", "draft", "draft>reviewer", "reviewer"]},
  "oxusFrame": {"nodes": {"clarify": {"d": "The first four minutes: pin down who the user is, what one unit of work looks like, and what \"done\" means for this system — before any box gets drawn.", "links": [{"label": "Session: round three is a different room", "url": "index.html#/w/1"}]}, "requirements": {"d": "Four minutes stating the non-functional requirements first — latency, consistency, availability targets — because they are what later decides which deep dive earns the twelve minutes it gets."}, "happy-path": {"d": "Eight minutes sketching the system end to end for the common case, with no depth in any one box yet — the shape of the whole thing before any one part is interrogated."}, "hard-part": {"d": "Twelve minutes, more than a third of the interview, spent on the one component that actually matters: grounding — how the system proves a cited value really sits on the page it claims to.\n\nThis is the deep dive the requirements step earlier was meant to justify. Spending it elsewhere would mean spending the interview's most valuable minutes on the wrong thing."}, "failure-eval": {"d": "Five minutes on how the system fails and how failure is measured — answered before she has to ask, because an unprompted failure story is itself a signal in a system design interview."}, "build-first": {"d": "The last two minutes: not a summary, but a direct answer to what you would actually build first — the answer a founding-engineer interview is really listening for."}}, "edges": {}, "walk": ["clarify", "requirements", "happy-path", "hard-part", "failure-eval", "build-first"]},
  "oxusIngest": {"nodes": {"native-pdf": {"d": "A PDF that was generated digitally and still has a real text layer, not a scanned image."}, "text-layer": {"d": "The text layer already embedded in a native PDF, extracted directly without OCR — the highest-confidence source of text in this pipeline."}, "scanned-pdf": {"d": "A PDF that is really a scanned image of a document, with no embedded text to extract."}, "ocr-layout": {"d": "OCR combined with layout analysis: it recovers both the text and where on the page each piece of text sits, which a citation later needs.\n\nThis step is also used for ERP screenshots, and it is the lowest-confidence source in this pipeline — its output is a best guess, not a re-read of ground truth."}, "spreadsheet": {"d": "A source spreadsheet, whose structure — rows, columns, sheets — is meaningful and worth preserving rather than flattening to text."}, "cells": {"d": "Spreadsheet cells extracted with their row and column position kept intact, so a downstream citation can point at a specific cell rather than an approximate location."}, "erp-screenshot": {"d": "A screenshot of an ERP system's screen, with no accessible text or structure of its own — handled the same way as a scanned page."}, "walkthrough-call": {"d": "An audio or video recording of a process walkthrough call, where a person describes how a control actually works."}, "transcript": {"d": "A timestamped transcript of the walkthrough call, so a later citation can point at the moment in the recording where something was said, not just quote it."}, "normalised-spans": {"d": "The single normalised representation every source type is converted into: a span carrying its document, page, bounding box, and — for recordings — a timestamp, plus a confidence score from whichever parser produced it.\n\nThis is the real design decision in the figure: once coordinates are lost at this step, no citation drawn later can recover them, however good the retrieval is."}, "per-tenant-index": {"d": "The retrieval index built from normalised spans, kept separate per tenant and combining lexical and dense (embedding) search.\n\nLexical matching handles the exact strings — invoice numbers, dollar amounts, dates — that dense embeddings are known to match poorly.", "links": [{"label": "Pattern: hybrid lexical and dense retrieval", "url": "SYSTEM%20DESIGN.html#/patterns/search/hybrid-rerank"}, {"label": "Session: evidence ingestion from messy documents", "url": "index.html#/s/2/4"}]}}, "edges": {"native-pdf>text-layer": {"d": "A native PDF's embedded text is read directly."}, "text-layer>normalised-spans": {"d": "Extracted text becomes spans, each still carrying its page and position."}, "scanned-pdf>ocr-layout": {"d": "A scanned page is OCR'd and its layout analyzed, since there is no text to extract directly."}, "ocr-layout>normalised-spans": {"d": "OCR output, with whatever confidence the parser assigns it, becomes spans like any other source."}, "spreadsheet>cells": {"d": "Rows and columns are read out as individual cells rather than flattened text."}, "cells>normalised-spans": {"d": "Each cell becomes a span that still knows its row and column."}, "erp-screenshot>ocr-layout": {"d": "A screenshot goes through the same OCR and layout path as a scanned page."}, "ocr-layout>normalised-spans#2": {"d": "Screenshot OCR output becomes spans the same way scanned-page OCR output does."}, "walkthrough-call>transcript": {"d": "The recording is transcribed with timestamps kept."}, "transcript>normalised-spans": {"d": "Transcript segments become spans carrying a timestamp instead of a page and bounding box."}, "normalised-spans>per-tenant-index": {"d": "Every span, regardless of source, is indexed the same way once it is normalised."}}, "walk": ["native-pdf", "native-pdf>text-layer", "text-layer", "text-layer>normalised-spans", "scanned-pdf", "scanned-pdf>ocr-layout", "erp-screenshot", "erp-screenshot>ocr-layout", "ocr-layout", "ocr-layout>normalised-spans", "spreadsheet", "spreadsheet>cells", "cells", "cells>normalised-spans", "walkthrough-call", "walkthrough-call>transcript", "transcript", "transcript>normalised-spans", "normalised-spans", "normalised-spans>per-tenant-index", "per-tenant-index"]},
  "oxusKB": {"nodes": {"request": {"d": "The first step of the process being modeled — a request is initiated, for example a purchase requisition. Appears identically in both the prior year's graph and this year's."}, "approve": {"d": "The approval step. In the prior year it goes straight through to posting; this year an extra manual edit step has appeared right after it."}, "post": {"d": "The final posting step that both years eventually reach — directly in the prior year, and via an extra manual edit this year."}, "manual-edit": {"d": "A manual editing step present this year that was not present in the prior year's process graph — the kind of change a year-over-year diff exists to surface."}, "flag-for-the-auditor": {"d": "The output of the diff: a flag pointing an auditor at exactly the place the process changed, rather than asking them to re-read the whole walkthrough looking for it.", "links": [{"label": "Session: walkthrough to flowchart, and the year-over-year base", "url": "index.html#/s/3/4"}]}}, "edges": {"request>approve": {"d": "Prior year: a request goes to approval with no step in between."}, "approve>post": {"d": "Prior year: an approved request posts directly."}, "request>approve#2": {"d": "This year: the same request still goes to approval first."}, "approve>manual-edit": {"d": "This year: after approval, a manual edit step now happens that did not exist before."}, "manual-edit>post": {"d": "The manually edited request still eventually posts, just via one more step than last year."}, "manual-edit>flag-for-the-auditor": {"d": "The appearance of this new manual step is exactly the kind of change the year-over-year diff is built to catch and flag."}}, "walk": ["request", "request>approve", "approve", "approve>post", "post", "request>approve#2", "approve", "approve>manual-edit", "manual-edit", "manual-edit>post", "manual-edit>flag-for-the-auditor", "flag-for-the-auditor"]},
  "passk": {"nodes": {"pass1": {"d": "pass^1: the fraction of tasks the agent solves in a single trial — whether it can do the task at all, once.\n\nOn tau-retail, gpt-4o's own paper reports this under 50%: on over half the tasks, even one attempt fails."}, "pass8": {"d": "pass^8: the fraction of tasks the agent solves on all eight of eight independent trials — whether it can be trusted to do the task reliably, not just once.\n\nThe same paper reports this under 25%. Nothing about the agent or the tasks changed between the two bars; only the number of attempts asked of it did.", "links": [{"label": "Pattern: gating a release on an eval score", "url": "SYSTEM%20DESIGN.html#/patterns/grounding/eval-gate"}, {"label": "Session: the alfred_ eval bench", "url": "index.html#/w/2"}]}}, "edges": {"pass1>pass8": {"d": "Asking the same agent to repeat the same tasks eight times instead of once roughly halves the fraction it can be trusted on — the gap a single pass@1 number hides."}}, "walk": ["pass1", "pass1>pass8", "pass8"]},
  "qkvAttention": {"nodes": {"q": {"d": "The query vector for the token currently being processed: a learned projection of its input embedding that encodes what this position is looking for.\n\nIt is compared against every position's key, including this token's own, to decide how much attention to pay to each one."}, "pos1": {"d": "Another position in the sequence, holding its own key and value vectors.\n\nIts key is what gets compared against the query to produce a score; its value is what actually gets carried into the output if that score turns out high. Here it wins the highest weight, 0.70."}, "pos2": {"d": "A second position, structurally identical to pos 1: its own key and value, scored against the same query.\n\nIn this example it ends up with the second-highest attention weight, 0.20."}, "pos3": {"d": "A third position: same structure again, key and value, scored against the same query.\n\nHere it receives the lowest weight, 0.10 — the query finds it least relevant, but not irrelevant. Softmax never assigns exactly zero."}, "output": {"d": "The output for the query's position: the weighted sum of every position's value vector, using the softmax weights computed from the scores.\n\nWith weights 0.70, 0.20 and 0.10 here, the output is dominated by pos 1's value but is not a copy of it — a little of every position leaks through."}}, "edges": {"q>pos1": {"d": "The raw attention score for pos 1: the dot product of the query and pos 1's key, q·k₁, before any normalisation."}, "q>pos2": {"d": "The raw score for pos 2, q·k₂, computed the same way and independently of pos 1's score."}, "q>pos3": {"d": "The raw score for pos 3, q·k₃ — the last of the three scores softmax turns into weights."}, "pos1>output": {"d": "0.70 of pos 1's value vector, added into the output — the largest of the three weights because pos 1's key matched the query best."}, "pos2>output": {"d": "0.20 of pos 2's value vector, added into the output alongside pos 1's contribution."}, "pos3>output": {"d": "0.10 of pos 3's value vector — the smallest contribution, but still present, since softmax weights are never exactly zero."}}, "walk": ["q", "q>pos1", "pos1", "q>pos2", "pos2", "q>pos3", "pos3", "pos1>output", "pos2>output", "pos3>output", "output"]},
  "queue": {"nodes": {"producer": {"d": "The service that puts work onto the queue. It has no idea how full the queue is unless the queue tells it.\n\nIn the top scenario it keeps sending at a constant rate no matter what happens downstream. In the bottom scenario it is the same code, but it slows down the moment the queue pushes back — the difference in behavior comes entirely from the signal the queue sends, not from anything the producer decides on its own."}, "queue-unbounded": {"d": "An unbounded queue: a buffer with no maximum size, so it accepts every item the producer sends, however many are already waiting.\n\nIt looks safe because nothing ever errors. Every item sitting in it is memory held and latency owed to whoever is waiting behind it, and when arrivals outpace processing this queue simply keeps growing until the process runs out of memory and is killed — the failure is delayed, not avoided."}, "worker": {"d": "The process that pulls items off the queue and does the work.\n\nIts throughput is the real ceiling on the whole system: however fast the producer sends, work leaves the queue only this fast. A queue's growth rate is simply the arrival rate minus this number."}, "queue-bounded": {"d": "A bounded queue: a buffer with a hard capacity limit, so once it is full it refuses new items instead of accepting them.\n\nRefusing work is a decision made on purpose, and it turns an invisible overload into a visible one — the producer gets an explicit signal (a full queue, a rejected write) instead of silently piling up work no one can see. That signal, and what the producer does with it, is backpressure.", "links": [{"label": "Pattern: a bounded queue as a write buffer", "url": "SYSTEM%20DESIGN.html#/patterns/scaling-writes/queue-buffer"}]}}, "edges": {"producer>queue-unbounded": {"d": "Work arrives fast and is always accepted; this queue has no concept of \"full\" to push back with."}, "queue-unbounded>worker": {"d": "Work leaves the queue at the fixed rate the worker can sustain, slower than it is arriving."}, "producer>queue-bounded": {"d": "Work arrives at the same rate as above, but this queue has a maximum size it will enforce."}, "queue-bounded>worker": {"d": "Work leaves at the same fixed worker rate as the top scenario — the difference between the two rows is entirely upstream of the worker."}, "queue-bounded>producer": {"d": "Once full, the queue rejects new items and that rejection reaches the producer directly — the backpressure signal the unbounded case never sends."}}, "walk": ["producer", "producer>queue-unbounded", "queue-unbounded", "queue-unbounded>worker", "worker", "producer>queue-bounded", "queue-bounded", "queue-bounded>worker", "queue-bounded>producer"]},
  "queueOverload": {"nodes": {"unbounded-trace": {"d": "The queue length of a system with no capacity limit, plotted against time under sustained overload.\n\nIt keeps climbing for as long as arrivals outpace departures, with no ceiling anywhere. Throughput can look unaffected on a shallow dashboard while latency and memory both climb without bound, until the process runs out of memory and dies all at once."}, "bounded-trace": {"d": "The queue length of a system with a capacity limit, under the same sustained overload.\n\nIt rises exactly like the unbounded queue at first, then flattens the moment it hits its cap. From that point on it refuses new work instead of accepting it, which is what keeps memory and latency from running away.", "links": [{"label": "Technique: queue as a buffer against bursts", "url": "SYSTEM%20DESIGN.html#/patterns/scaling-writes/queue-buffer"}]}, "shed": {"d": "The point where a full, bounded queue starts refusing incoming work instead of queueing it.\n\nRejecting work is information the caller can act on immediately: retry elsewhere, back off, surface an error. A silent queue that eventually falls over gives the caller nothing to act on until it is too late.", "links": [{"label": "Technique: load shedding", "url": "SYSTEM%20DESIGN.html#/patterns/scaling-writes/load-shedding"}]}, "utilisation-curve": {"d": "The expected number of items waiting, E[N], as a function of utilisation ρ for a simple single-server queue: E[N] = ρ/(1−ρ).\n\nAt ρ = 0.5 the expected queue is only 1 item; at ρ = 0.9 it is already 9. The curve does not rise smoothly from there — it goes vertical as ρ approaches 1. This is the mathematical reason a system run 'a bit hot' can look fine right up until it very suddenly is not."}}, "edges": {}, "walk": ["unbounded-trace", "bounded-trace", "shed", "utilisation-curve"]},
  "retry": {"nodes": {"clients": {"d": "The callers making requests to the service, including the ones about to retry a call that just failed or timed out."}, "service": {"d": "The service under load. In the top scenario it is already at capacity when the retries land; in the bottom scenario the same service is recovering, because the retries are spread out instead of arriving in one synchronized wave.", "links": [{"label": "Pattern: timeouts and retries with backoff", "url": "SYSTEM%20DESIGN.html#/patterns/reliability/timeouts-retries"}]}}, "edges": {"clients>service": {"d": "Requests and retries all arrive together, with no delay between a failure and the next attempt — exactly when the service has the least spare capacity to serve them."}, "clients>service#2": {"d": "The same clients retry, but each first waits a randomized (jittered) backoff, so their retries land spread out over time instead of in one synchronized wave that recreates the spike."}}, "walk": ["clients", "clients>service", "service", "clients>service#2"]},
  "sigmoidDerivative": {"nodes": {"sigmoid-curve": {"d": "The logistic sigmoid, σ(x) = 1/(1+e⁻ˣ), plotted from x = −6 to x = 6.\n\nIt maps any real number to a value between 0 and 1, S-shaped: flat near both ends and steepest through the middle."}, "derivative-curve": {"d": "The derivative of the sigmoid, σ(x)(1−σ(x)), plotted on the same x-axis.\n\nIt is a bell shape that peaks at exactly 0.25 at x = 0 and decays toward 0 as x moves toward either extreme. This is literally how much the sigmoid's output changes per unit change in x, at every point."}, "peak": {"d": "The single highest point the sigmoid's derivative ever reaches: 0.25, at x = 0, where σ(x) = 0.5.\n\nThis is also the point of maximum uncertainty for a unit using this activation — the gradient is largest exactly where the unit does not yet know which way to lean, and smallest once it is already confident."}}, "edges": {}, "walk": ["sigmoid-curve", "peak", "derivative-curve"]},
  "skew": {"nodes": {"requests": {"d": "All incoming traffic, before it is routed to a partition by its key."}, "hash": {"d": "The hash function that maps each request's partition key — here, user id — to one of the partitions.\n\nHashing is deterministic and spreads keys uniformly across the output space: the same user id always lands on the same partition, and different user ids land roughly evenly overall. That guarantee is about keys, not about the traffic those keys happen to carry.", "links": [{"label": "Pattern: a hot partition after a fair hash", "url": "SYSTEM%20DESIGN.html#/patterns/scaling-writes/hot-partition"}]}, "partitions": {"d": "The seven partitions that are not the hot one. Each holds a roughly even share of distinct users, and because no single user among them generates much traffic, none of these come close to the capacity line."}, "hot-partition": {"d": "The one partition that happens to hold a single very active user — in this example, a user responsible for about 4% of all events on its own.\n\nHashing put it here fairly: the hash function did not favor this partition, one key's real-world traffic did. Because every one of that user's events hashes to the same partition, that partition's ceiling becomes the whole system's ceiling, however many other partitions sit idle beside it."}}, "edges": {"requests>hash": {"d": "Every request carries a partition key that the hash function reads to decide where it goes."}, "hash>partitions": {"d": "Most users hash here and spread their comparatively small, even traffic across these partitions."}, "hash>hot-partition": {"d": "One user's key hashes here every time, concentrating a disproportionate share of all traffic on a single partition."}}, "walk": ["requests", "requests>hash", "hash", "hash>partitions", "partitions", "hash>hot-partition", "hot-partition"]},
  "skipLocked": {"nodes": {"job-1": {"d": "A row in the jobs table, queued for a worker to claim.\n\nFOR UPDATE SKIP LOCKED lets a worker lock a row like this one without waiting on rows another worker already holds. Worker 1 locks this one first."}, "job-2": {"d": "Another queued row, locked in the same claim transaction as job 1 by Worker 1.\n\nA worker typically claims a small batch at once rather than one row at a time."}, "job-3": {"d": "A queued row that Worker 2 claims.\n\nBecause jobs 1 and 2 are already locked, SKIP LOCKED makes Worker 2 skip straight past them to this row instead of blocking and waiting."}, "job-4": {"d": "Another row Worker 2 claims in the same batch as job 3."}, "job-5": {"d": "A row still waiting, claimed by neither worker yet.\n\nIt goes to whichever worker next runs a claim query and finds it unlocked."}, "worker-1": {"d": "A process that polls the jobs table and claims a batch of unclaimed rows to work on.\n\nSELECT ... FOR UPDATE SKIP LOCKED is what lets it lock jobs 1 and 2 without blocking on, or being blocked by, whatever another worker is doing.", "links": [{"label": "Postgres docs: FOR UPDATE SKIP LOCKED", "url": "https://www.postgresql.org/docs/current/sql-select.html"}]}, "worker-2": {"d": "A second, concurrent worker running the identical claim query.\n\nBecause Worker 1's rows are locked, SKIP LOCKED makes this query skip them instead of waiting, so the two workers never serialise on the same rows.", "links": [{"label": "Technique: claiming a queue with SKIP LOCKED", "url": "SYSTEM%20DESIGN.html#/patterns/contention/claim-skip-locked"}]}, "event-trigger": {"d": "A notification fired when a new job is written, used to wake a worker immediately instead of waiting for the next poll.\n\nThis cuts the drain latency from a cron interval's worst case (about ninety seconds) down to about three seconds.", "links": [{"label": "Postgres docs: LISTEN, triggering on the event", "url": "https://www.postgresql.org/docs/current/sql-listen.html"}]}, "cron": {"d": "A periodic poll that runs on a fixed schedule regardless of whether anything triggered a drain.\n\nIt is kept as the backstop for whatever the event path misses — a dropped notification, a worker that was down — so the queue still drains even if the event-driven path fails silently.", "links": [{"label": "Technique: keeping a backstop after moving to events", "url": "SYSTEM%20DESIGN.html#/patterns/long-running/retries-dlq"}]}}, "edges": {"worker-1>job-1": {"d": "Worker 1's claim query locks this row."}, "worker-1>job-2": {"d": "The same claim locks this row too, in the same batch."}, "worker-2>job-3": {"d": "Worker 2's claim query skips the locked rows and takes this one instead."}, "worker-2>job-4": {"d": "Worker 2 claims this row in the same batch."}, "event-trigger>job-1": {"d": "A new job firing the event is what wakes a worker to claim it quickly."}, "cron>job-4": {"d": "The periodic poll would also have picked up this row if the event path had missed it."}}, "walk": ["worker-1", "worker-1>job-1", "job-1", "worker-1>job-2", "job-2", "worker-2", "worker-2>job-3", "job-3", "worker-2>job-4", "job-4", "job-5", "event-trigger", "event-trigger>job-1", "cron", "cron>job-4"]},
  "softmaxCrossEntropy": {"nodes": {"loss-curve": {"d": "Cross-entropy loss, −log(p), plotted against p: the probability the model assigned to the correct class.\n\nIt is large when p is small (confidently wrong, or just unsure) and falls toward 0 only as p approaches 1. Unlike squared error, it is unbounded as p → 0: being very confidently wrong is punished arbitrarily hard."}, "gradient-curve": {"d": "The magnitude of the loss gradient with respect to the true class's logit, exactly (1−p), plotted on the same p axis.\n\nIt stays large for as long as p is far from 1 and shrinks smoothly to 0 only once the prediction is both confident and correct. The model keeps getting a strong training signal for exactly as long as it needs one."}}, "edges": {}, "walk": ["loss-curve", "gradient-curve"]},
  "source": {"nodes": {"vocal-folds": {"d": "The vocal folds (vocal cords), which vibrate to produce a buzz at the fundamental frequency, F0.\n\nThis buzz is the source in the source-filter model, and it carries pitch — f0_mean is a direct measurement of this stage.", "links": [{"label": "Session: the source-filter model", "url": "index.html#/s/5/3"}]}, "vocal-tract": {"d": "The vocal tract: throat, mouth and nasal cavity, acting as a resonant tube.\n\nIt filters the source buzz, boosting some frequencies (the formants) and damping others depending on tongue and jaw position; this filtering carries speaker identity, not pitch.", "links": [{"label": "Alaap plan, stage 2: source and filter, what describes a voice", "url": "ALAAP.html#/plan/stage-2"}]}, "voice": {"d": "The voice that actually leaves the mouth: the source buzz after passing through the vocal tract's filter.\n\nEverything you hear is this combination — you cannot recover the pure source or the pure filter response by listening alone, which is exactly why separate measurements are needed for each.", "links": [{"label": "AI Engineering from Scratch: speaker recognition and verification", "url": "https://github.com/rohitg00/ai-engineering-from-scratch/tree/main/phases/06-speech-and-audio/06-speaker-recognition-verification"}]}}, "edges": {"vocal-folds>vocal-tract": {"d": "The source signal, F0's buzz, is fed into the tract to be filtered."}, "vocal-tract>voice": {"d": "The filtered signal leaves as the audible voice."}}, "walk": ["vocal-folds", "vocal-folds>vocal-tract", "vocal-tract", "vocal-tract>voice", "voice"]},
  "spectrogramReading": {"nodes": {"harmonics": {"d": "The evenly spaced vertical lines: the harmonics of the voice, at f0, 2f0, 3f0 and so on — integer multiples of the fundamental frequency.\n\nTheir spacing is f0 itself: closer-packed harmonics mean a lower pitch, wider-spaced harmonics mean a higher one. Their individual heights are shaped by the vocal tract, not by the source."}, "envelope": {"d": "The smooth curve traced across the tops of the harmonics: the spectral envelope, set by the resonances of the vocal tract.\n\nIts shape is what distinguishes one vowel, or one speaker, from another at the same pitch. Change the source (the buzz) and the envelope stays the same; change the vocal tract and the envelope changes.", "links": [{"label": "Alaap: source and filter, what describes a voice", "url": "ALAAP.html#/plan/stage-2"}]}, "formant-f1": {"d": "F1, the first formant: the lowest-frequency peak of the spectral envelope.\n\nIt shifts mainly with tongue height and jaw opening, and is one of the two or three formants that most determine which vowel is being produced."}, "formant-f2": {"d": "F2, the second formant: the next peak up in the envelope.\n\nIt shifts mainly with how far forward or back the tongue sits, and together with F1 largely determines vowel identity."}, "formant-f3": {"d": "F3, the third formant: a smaller, higher-frequency peak.\n\nIt contributes less to vowel identity than F1 and F2, but carries speaker-specific detail, since vocal-tract length affects all formants without shifting them proportionally."}, "tilt-line": {"d": "A straight reference line tracking the envelope's overall downward drift from low frequency to high frequency: the spectral tilt.\n\nIt is meant to be a source-side measurement, describing the shape of the glottal pulse (roughly, how breathy versus pressed the voicing is) independent of pitch. In practice it partly measures the buzz rate, f0, instead — an estimator confound, and exactly how an axis meant to separate two things ends up not separating them.", "links": [{"label": "Alaap: frequency, and how estimators lie", "url": "ALAAP.html#/plan/stage-11"}]}}, "edges": {}, "walk": ["harmonics", "envelope", "formant-f1", "formant-f2", "formant-f3", "tilt-line"]},
  "sqliteTemplate": {"nodes": {"base-snapshot": {"d": "The seed data for one test case, before it has been copied anywhere.\n\nIt is just a file (for the SQLite approach) or a database (for the template approach) — the interesting difference is what happens when it gets copied per case.", "links": [{"label": "Technique: environment snapshots, two ways to build one", "url": "SYSTEM%20DESIGN.html#/patterns/agent-durability/env-snapshots"}]}, "case-sqlite": {"d": "A private copy of the base snapshot, one plain file per test case.\n\nCopying a file is essentially free, so this scales to hundreds of cases and is trivial to inspect by hand — at the price of running on a different database engine than production."}, "not-the-real-engine": {"d": "What a SQLite snapshot cannot test: anything that depends on the real database engine's own behaviour.\n\nThere is no row-level security to enforce and different type-affinity rules than Postgres, so a case can pass here while hiding a bug that only exists against the real engine."}, "template-database": {"d": "A Postgres database marked as a template, so the engine itself knows how to clone it.\n\nUnlike a SQLite file, this stays on the exact engine production runs on.", "links": [{"label": "Postgres docs: template databases", "url": "https://www.postgresql.org/docs/current/manage-ag-templatedbs.html"}]}, "case-database": {"d": "A fresh Postgres database, cloned per test case from the template with CREATE DATABASE ... TEMPLATE.\n\nAt modest scale this approaches SQLite-file speed, but because it is still Postgres, row-level security and type rules behave exactly as they do in production."}, "costs-a-server": {"d": "The real cost of the template approach: a live Postgres server has to be running in the test path.\n\nThat is a heavier dependency than a bare file — the trade being made for fidelity."}}, "edges": {"base-snapshot>case-sqlite": {"d": "Copying the base snapshot's file gives each case an isolated SQLite database."}, "case-sqlite>not-the-real-engine": {"d": "That speed and simplicity comes at the cost of testing a different engine than production."}, "template-database>case-database": {"d": "CREATE DATABASE ... TEMPLATE clones the template into a fresh database for one case."}, "case-database>costs-a-server": {"d": "Getting a real Postgres database per case means a server has to be available to clone from."}}, "walk": ["base-snapshot", "base-snapshot>case-sqlite", "case-sqlite", "case-sqlite>not-the-real-engine", "not-the-real-engine", "template-database", "template-database>case-database", "case-database", "case-database>costs-a-server", "costs-a-server"]},
  "storage": {"nodes": {"write": {"d": "A write request arriving at the storage engine."}, "memtable": {"d": "An in-memory, sorted buffer that absorbs writes as they arrive.\n\nWriting here is cheap: it is an in-memory insert, not a disk seek. Once it fills, its contents flush to disk as an immutable sorted file — this is what makes an LSM-tree's writes fast."}, "sst-files": {"d": "The sorted files on disk that a memtable's contents become once flushed, later merged together in the background by compaction.\n\nA read may need to check several of these layers, newest first, before it finds a key or concludes it is absent. Compaction is what keeps the layer count from growing forever, at the cost of extra background IO.", "links": [{"label": "Pattern: a write-optimized storage engine", "url": "SYSTEM%20DESIGN.html#/patterns/scaling-writes/write-optimized"}]}, "root": {"d": "The top of a B-tree: a page that routes a lookup toward the correct child page by comparing keys."}, "page": {"d": "A leaf page holding actual rows or values, updated in place when a write touches a key stored there.\n\nBecause the write happens in place rather than by appending, its cost is dominated by the random disk IO of locating and rewriting that exact page — the opposite trade-off from the LSM-tree's append-only writes."}}, "edges": {"write>memtable": {"d": "The write lands in memory first; nothing touches disk yet."}, "memtable>sst-files": {"d": "When the memtable fills, it flushes as one new sorted file; older files are merged together later by compaction."}, "root>page": {"d": "A lookup compares its key against the root and descends to the child page that could contain it."}, "root>page#2": {"d": "The same root routes a different lookup, with a different key, to a different child page."}}, "walk": ["write", "write>memtable", "memtable", "memtable>sst-files", "sst-files", "root", "root>page", "root>page#2", "page"]},
  "tail": {"nodes": {"request": {"d": "A single request that fans out to many shards and must wait for all of them to answer before it can finish.\n\nIts latency is set by the slowest shard it touches, not the average one — that is the mechanism behind tail-latency amplification.", "links": [{"label": "Pattern: timeouts and retries against a slow dependency", "url": "SYSTEM%20DESIGN.html#/patterns/reliability/timeouts-retries"}]}, "shards-normal": {"d": "The shards that respond quickly on this request. Each shard is independently slow with probability 1%, so on any given request most of the 100 shards (12 are drawn here to stand for them) behave normally."}, "shards-slow": {"d": "The shards that happen to be slow on this particular request.\n\nWith 100 independent shards each slow 1% of the time, the chance that at least one of them is slow works out to about 63% — so on most requests, at least one shard looks like these."}}, "edges": {"request>shards-normal": {"d": "The request fans out to every shard it needs an answer from; most return quickly."}, "request>shards-slow": {"d": "The same fan-out reaches the unlucky shards too, and the request cannot finish until they answer, however many of the others already have."}}, "walk": ["request", "request>shards-normal", "shards-normal", "request>shards-slow", "shards-slow"]},
  "vectors": {"nodes": {"vector-a": {"d": "A vector a in two dimensions, drawn from the origin.\n\nIts direction and length both matter for the plain dot product, but only its direction matters once the lengths are divided out to get cosine similarity.", "links": [{"label": "Session: vectors and matrices", "url": "index.html#/s/3/2"}]}, "vector-b": {"d": "A second vector b, at some angle θ from a.\n\nThe smaller that angle, the closer cosθ is to 1 and the more similar the two vectors are judged to be, regardless of how long either one is."}, "vector-c": {"d": "A vector c = 0.5a: exactly half the length of a, pointing in exactly the same direction.\n\nBecause cosine similarity divides out length, cos(a, c) = 1 even though |c| is half of |a| — the concrete case behind \"two embeddings with different magnitudes can still mean the same thing.\"", "links": [{"label": "System design guide: vector search", "url": "SYSTEM%20DESIGN.html#/patterns/search/vector"}]}, "theta": {"d": "The angle between a and b.\n\nIt is the only thing cosine similarity measures once the magnitudes |a| and |b| are divided out of the dot product.", "links": [{"label": "AI Engineering from Scratch: norms and distances", "url": "https://github.com/rohitg00/ai-engineering-from-scratch/tree/main/phases/01-math-foundations/14-norms-and-distances"}]}}, "edges": {}, "walk": ["vector-a", "vector-b", "theta", "vector-c"]},
  "zenEffects": {"nodes": {"tool-call": {"d": "A function call the agent's framework asks a tool to run, with its name and arguments.\n\nIn a replay this is the decision point: the harness has to classify what the call would do to the world before it can decide whether to answer it from a recording, run it through a ledger, or refuse to let it fire for real. An email send, a calendar read and a refund charge all arrive here in the same shape and get sorted by their effect.", "links": [{"label": "Technique: sorting tools by what they do to the world", "url": "SYSTEM%20DESIGN.html#/patterns/agent-safety/effect-classes"}]}, "read": {"d": "A tool call that only returns information and leaves no trace of having happened.\n\nBecause it has no effect, any answer consistent with the recording is safe to return, so a read can always be served from the recording. What happens on a miss (a read the recording never saw) still needs an explicit on_miss policy rather than a silent default."}, "idempotent-write": {"d": "A tool call that changes state but is safe to repeat, because the same inputs always produce the same outcome.\n\nIt can go through a ledger keyed on session, step and the canonical form of the arguments, so a second identical call returns the stored result instead of writing a second time.", "links": [{"label": "Technique: idempotency keys for safe retries", "url": "SYSTEM%20DESIGN.html#/patterns/multi-step/idempotency"}]}, "external-effect": {"d": "A tool call that reaches outside the system under test: it sends an email, charges a card, files a refund.\n\nA forked replay exists to see what's different when something changes, so letting a call like this fire for real would corrupt the very world you're testing against. It must never pass through by default; a new one the recording never saw needs its own explicit path — a dry-run adapter, or a hard failure — never a silent live call.", "links": [{"label": "Technique: human-in-the-loop or undo for risky effects", "url": "SYSTEM%20DESIGN.html#/patterns/agent-safety/hitl-undo"}]}}, "edges": {"tool-call>read": {"d": "The call is classified as read-only and routed to the answer-from-recording path."}, "tool-call>idempotent-write": {"d": "The call is classified as idempotent and routed through the ledger instead."}, "tool-call>external-effect": {"d": "The call is classified as having an external effect and blocked from passing through by default."}}, "walk": ["tool-call", "tool-call>read", "read", "tool-call>idempotent-write", "idempotent-write", "tool-call>external-effect", "external-effect"]},
  "zenmlStack": {"nodes": {"step-load": {"d": "A step in a ZenML pipeline: a Python function decorated to run as one traceable unit of the pipeline.\n\nIts job here is to load data and hand off a versioned artifact to the next step.", "links": [{"label": "ZenML docs: steps and pipelines", "url": "https://docs.zenml.io/concepts/steps_and_pipelines"}]}, "step-train": {"d": "The training step, which consumes the loaded dataset artifact and produces a trained model artifact."}, "step-evaluate": {"d": "The evaluation step, which consumes the trained model and produces metrics.\n\nLike every step, its inputs and outputs are versioned artifacts, not values passed in memory, so the run can be inspected after the fact."}, "dataset-v3": {"d": "A versioned artifact: the specific dataset this run of the pipeline loaded, stored with lineage back to the step that produced it.\n\nThe version number means a later run can be diffed against, or re-fed, this exact dataset rather than whatever the data source currently contains.", "links": [{"label": "ZenML docs: artifacts and lineage", "url": "https://docs.zenml.io/concepts/artifacts"}]}, "model-v7": {"d": "A versioned artifact: the specific trained model this run produced."}, "metrics": {"d": "A versioned artifact: the evaluation numbers this run produced, tied to the exact model and dataset that generated them."}, "stack": {"d": "The set of infrastructure components — orchestrator, artifact store, and others — that decides where and how the pipeline's steps actually run.\n\nThe pipeline's code doesn't change when the stack does; swapping the orchestrator or the artifact store changes execution without touching the steps.", "links": [{"label": "ZenML docs: core concepts", "url": "https://docs.zenml.io/getting-started/core-concepts"}]}}, "edges": {"step-load>step-train": {"d": "The loaded dataset artifact flows into the training step."}, "step-train>step-evaluate": {"d": "The trained model artifact flows into the evaluation step."}, "step-load>dataset-v3": {"d": "Loading produces this versioned dataset artifact."}, "step-train>model-v7": {"d": "Training produces this versioned model artifact."}, "step-evaluate>metrics": {"d": "Evaluating produces this versioned metrics artifact."}, "stack>step-evaluate": {"d": "The stack's orchestrator is what actually executes each step, including this one."}}, "walk": ["step-load", "step-load>dataset-v3", "dataset-v3", "step-load>step-train", "step-train", "step-train>model-v7", "model-v7", "step-train>step-evaluate", "step-evaluate", "step-evaluate>metrics", "metrics", "stack", "stack>step-evaluate"]}
});
